/* 3mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

  /* Create restrict-qualified local views of the 2D arrays.
     These express the fact that the different matrices do not alias,
     which helps the compiler vectorize and reorder memory accesses safely. */
  DATA_TYPE       (* restrict E_)[nj] = E;
  DATA_TYPE       (* restrict A_)[nk] = A;
  const DATA_TYPE (* restrict B_)[nj] = B;

  DATA_TYPE       (* restrict F_)[nl] = F;
  DATA_TYPE       (* restrict C_)[nm] = C;
  const DATA_TYPE (* restrict D_)[nl] = D;

  DATA_TYPE       (* restrict G_)[nl] = G;

  /* Cache the (possibly macro-based) loop bounds in local consts. */
  const int ni_ = _PB_NI;
  const int nj_ = _PB_NJ;
  const int nk_ = _PB_NK;
  const int nl_ = _PB_NL;
  const int nm_ = _PB_NM;

  const DATA_TYPE zero = SCALAR_VAL(0.0);

#pragma scop
  /* E := A*B
     Reordered to an i-k-j traversal:
       - For each row i of A and E, we
         * first zero the entire row of E,
         * then for each k accumulate A[i][k] * B[k][*] into that row.
     For each fixed (i,j), the sequence of operations is still:
         E[i][j] = 0;
         for k = 0..nk-1: E[i][j] += A[i][k] * B[k][j];
     so the floating-point evaluation order for each element is preserved. */

  for (i = 0; i < ni_; ++i)
    {
      DATA_TYPE *E_row = E_[i];

      /* Initialize row i of E. */
      for (j = 0; j < nj_; ++j)
        E_row[j] = zero;

      /* Accumulate A[i][k] * B[k][j] into row i of E. */
      for (k = 0; k < nk_; ++k)
        {
          const DATA_TYPE        aik   = A_[i][k];
          const DATA_TYPE *B_row = B_[k];

          for (j = 0; j < nj_; ++j)
            E_row[j] += aik * B_row[j];
        }
    }

  /* F := C*D
     Same i-k-j restructuring for better data locality:
       - C rows and D rows are accessed contiguously,
       - F rows are reused in cache while their values are accumulated. */

  for (i = 0; i < nj_; ++i)
    {
      DATA_TYPE *F_row = F_[i];

      /* Initialize row i of F. */
      for (j = 0; j < nl_; ++j)
        F_row[j] = zero;

      /* Accumulate C[i][k] * D[k][j] into row i of F. */
      for (k = 0; k < nm_; ++k)
        {
          const DATA_TYPE        cik   = C_[i][k];
          const DATA_TYPE *D_row = D_[k];

          for (j = 0; j < nl_; ++j)
            F_row[j] += cik * D_row[j];
        }
    }

  /* G := E*F
     Again use i-k-j ordering:
       - E rows and F rows are both accessed contiguously,
       - each row of G remains in cache during its accumulation.
     Per-element accumulation order over k is identical to the original code. */

  for (i = 0; i < ni_; ++i)
    {
      DATA_TYPE *G_row = G_[i];

      /* Initialize row i of G. */
      for (j = 0; j < nl_; ++j)
        G_row[j] = zero;

      /* Accumulate E[i][k] * F[k][j] into row i of G. */
      for (k = 0; k < nj_; ++k)
        {
          const DATA_TYPE        eik   = E_[i][k];
          const DATA_TYPE *F_row = F_[k];

          for (j = 0; j < nl_; ++j)
            G_row[j] += eik * F_row[j];
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_3mm (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(E),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(F),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D),
	      POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
