/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Use restrict-qualified local pointers to help the compiler with aliasing.
   - Separate initialization of E, F, and G from the main computation
     to improve vectorization.
   - Block (tile) all three matrix multiplications in i, j, and k
     dimensions to improve cache locality.
   - Keep the order of accumulation in k identical to the original
     for each (i,j) element, preserving floating-point semantics.
*/
static void __attribute__((noinline, flatten))
kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  /* Local restrict-qualified views of the input/output arrays.
     This gives the compiler stronger aliasing guarantees while
     preserving the original memory layout and semantics. */
  DATA_TYPE (*restrict E_)[nj] = E;
  DATA_TYPE (*restrict A_)[nk] = A;
  DATA_TYPE (*restrict B_)[nj] = B;
  DATA_TYPE (*restrict F_)[nl] = F;
  DATA_TYPE (*restrict C_)[nm] = C;
  DATA_TYPE (*restrict D_)[nl] = D;
  DATA_TYPE (*restrict G_)[nl] = G;

  /* Local copies of loop bounds (PolyBench uses the _PB_* macros
     to allow for potential runtime tuning). */
  const int niPB = _PB_NI;
  const int njPB = _PB_NJ;
  const int nkPB = _PB_NK;
  const int nlPB = _PB_NL;
  const int nmPB = _PB_NM;

  const DATA_TYPE zero = SCALAR_VAL(0.0);

  /* Block sizes chosen to fit working tiles of A/B/E, C/D/F, E/F/G
     in the L1/L2 caches on a typical x86_64 machine. Edge tiles are
     handled explicitly, so dimensions need not be multiples of the
     block sizes. */
  const int I_BLOCK = 32;
  const int J_BLOCK = 32;
  const int K_BLOCK = 32;

#pragma scop
  /* E := A*B */

  /* Initialize E to zero in a separate, vector-friendly pass. */
  for (int i = 0; i < niPB; ++i)
  {
#pragma GCC ivdep
    for (int j = 0; j < njPB; ++j)
      E_[i][j] = zero;
  }

  /* Blocked matrix multiplication:
     E (niPB x njPB) = A (niPB x nkPB) * B (nkPB x njPB)

     Loop order: ii, kk, jj, then i, k, j

     For each fixed (i,j), the innermost accumulation over k still
     visits k in strictly increasing order 0..nkPB-1 (in contiguous
     tiles), so the floating-point results are bitwise identical to
     the original triple loop. */
  for (int ii = 0; ii < niPB; ii += I_BLOCK)
  {
    int i_end = ii + I_BLOCK;
    if (i_end > niPB) i_end = niPB;

    for (int kk = 0; kk < nkPB; kk += K_BLOCK)
    {
      int k_end = kk + K_BLOCK;
      if (k_end > nkPB) k_end = nkPB;

      for (int jj = 0; jj < njPB; jj += J_BLOCK)
      {
        int j_end = jj + J_BLOCK;
        if (j_end > njPB) j_end = njPB;

        for (int i = ii; i < i_end; ++i)
        {
          for (int k = kk; k < k_end; ++k)
          {
            DATA_TYPE aik = A_[i][k];
#pragma GCC ivdep
            for (int j = jj; j < j_end; ++j)
              E_[i][j] += aik * B_[k][j];
          }
        }
      }
    }
  }

  /* F := C*D */

  /* Initialize F to zero. */
  for (int i = 0; i < njPB; ++i)
  {
#pragma GCC ivdep
    for (int j = 0; j < nlPB; ++j)
      F_[i][j] = zero;
  }

  /* Blocked matrix multiplication:
     F (njPB x nlPB) = C (njPB x nmPB) * D (nmPB x nlPB) */
  for (int ii = 0; ii < njPB; ii += I_BLOCK)
  {
    int i_end = ii + I_BLOCK;
    if (i_end > njPB) i_end = njPB;

    for (int kk = 0; kk < nmPB; kk += K_BLOCK)
    {
      int k_end = kk + K_BLOCK;
      if (k_end > nmPB) k_end = nmPB;

      for (int jj = 0; jj < nlPB; jj += J_BLOCK)
      {
        int j_end = jj + J_BLOCK;
        if (j_end > nlPB) j_end = nlPB;

        for (int i = ii; i < i_end; ++i)
        {
          for (int k = kk; k < k_end; ++k)
          {
            DATA_TYPE cik = C_[i][k];
#pragma GCC ivdep
            for (int j = jj; j < j_end; ++j)
              F_[i][j] += cik * D_[k][j];
          }
        }
      }
    }
  }

  /* G := E*F */

  /* Initialize G to zero. */
  for (int i = 0; i < niPB; ++i)
  {
#pragma GCC ivdep
    for (int j = 0; j < nlPB; ++j)
      G_[i][j] = zero;
  }

  /* Blocked matrix multiplication:
     G (niPB x nlPB) = E (niPB x njPB) * F (njPB x nlPB) */
  for (int ii = 0; ii < niPB; ii += I_BLOCK)
  {
    int i_end = ii + I_BLOCK;
    if (i_end > niPB) i_end = niPB;

    for (int kk = 0; kk < njPB; kk += K_BLOCK)
    {
      int k_end = kk + K_BLOCK;
      if (k_end > njPB) k_end = njPB;

      for (int jj = 0; jj < nlPB; jj += J_BLOCK)
      {
        int j_end = jj + J_BLOCK;
        if (j_end > nlPB) j_end = nlPB;

        for (int i = ii; i < i_end; ++i)
        {
          for (int k = kk; k < k_end; ++k)
          {
            DATA_TYPE eik = E_[i][k];
#pragma GCC ivdep
            for (int j = jj; j < j_end; ++j)
              G_[i][j] += eik * F_[k][j];
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
