   *           for j
   *             result[i][j] += row_k[j] * loaded_scalar;
   *
   *   Now the innermost loop walks contiguous memory in j for both the
   *   accumulation matrix row and the k-th row of the right-hand operand.
   *   This greatly improves spatial locality and enables straightforward
   *   vectorization by the compiler.
   *
   * - Row pointers are cached in local (restrict-qualified) pointers to
   *   reduce address computation and give the compiler stronger aliasing
   *   guarantees, without changing observable behavior.
   */

  /* E := A*B */
  for (i = 0; i < _PB_NI; i++)
    {
      /* Row pointers for better locality and fewer address calculations. */
      DATA_TYPE * restrict E_row = E[i];
      const DATA_TYPE * restrict A_row = A[i];

      /* Initialize row E[i][:] once (logically equivalent to original code). */
      for (j = 0; j < _PB_NJ; j++)
        E_row[j] = SCALAR_VAL(0.0);

      /* Accumulate A[i][k] * B[k][:] into E[i][:]. */
      for (k = 0; k < _PB_NK; ++k)
        {
          const DATA_TYPE a_ik = A_row[k];
          const DATA_TYPE * restrict B_row = B[k]; /* row-major, contiguous in j */

          /* Inner loop now walks contiguous memory in both E_row and B_row. */
          for (j = 0; j < _PB_NJ; ++j)
            E_row[j] += a_ik * B_row[j];
        }
    }

  /* F := C*D */
  for (i = 0; i < _PB_NJ; i++)
    {
      DATA_TYPE * restrict F_row = F[i];
      const DATA_TYPE * restrict C_row = C[i];

      for (j = 0; j < _PB_NL; j++)
        F_row[j] = SCALAR_VAL(0.0);

      for (k = 0; k < _PB_NM; ++k)
        {
          const DATA_TYPE c_ik = C_row[k];
          const DATA_TYPE * restrict D_row = D[k];

          for (j = 0; j < _PB_NL; ++j)
            F_row[j] += c_ik * D_row[j];
        }
    }

  /* G := E*F */
  for (i = 0; i < _PB_NI; i++)
    {
      DATA_TYPE * restrict G_row = G[i];
      const DATA_TYPE * restrict E_row = E[i];

      for (j = 0; j < _PB_NL; j++)
        G_row[j] = SCALAR_VAL(0.0);

      for (k = 0; k < _PB_NJ; ++k)
        {
          const DATA_TYPE e_ik = E_row[k];
          const DATA_TYPE * restrict F_row = F[k];

          for (j = 0; j < _PB_NL; ++j)
            G_row[j] += e_ik * F_row[j];
        }
    }
#pragma endscop

}


