  DATA_TYPE (*restrict A_)[nk] = A;
  DATA_TYPE (*restrict B_)[nj] = B;
  DATA_TYPE (*restrict F_)[nl] = F;
  DATA_TYPE (*restrict C_)[nm] = C;
  DATA_TYPE (*restrict D_)[nl] = D;
  DATA_TYPE (*restrict G_)[nl] = G;

  /* Use the PolyBench problem-size macros for loop bounds.
   * These may differ from the raw sizes in parameter lists on
   * some configurations, so we keep them as the canonical bounds.
   */
  const int ni_pb = _PB_NI;
  const int nj_pb = _PB_NJ;
  const int nk_pb = _PB_NK;
  const int nl_pb = _PB_NL;
  const int nm_pb = _PB_NM;

  const DATA_TYPE zero = SCALAR_VAL(0.0);

#pragma scop
  /* E := A*B
   *
   * Original order: i, j, k
   *   for each (i,j): initialize E[i][j] = 0, then accumulate over k.
   *
   * Optimized order: i, (initialize whole row j), k, j
   *   - For each fixed (i,j), the sequence of operations on E[i][j]
   *     is still: set to 0, then add A[i][k]*B[k][j] for k=0..nk-1
   *     in increasing k. Only operations for different (i,j) are
   *     interleaved, so floating-point results remain bitwise
   *     identical for each element.
   *
   * Data locality:
   *   - A[i][k] is read along k (row-major contiguous).
   *   - B[k][j] is read along j (row-major contiguous) using B's row k.
   *   - E[i][j] is written/updated along j (row-major contiguous).
   * This is much more cache- and SIMD-friendly than the original i,j,k
   * ordering where B was accessed with a large stride.
   */
  for (i = 0; i < ni_pb; i++)
  {
    DATA_TYPE *restrict Ei = E_[i];

    /* Initialize row i of E. */
    for (j = 0; j < nj_pb; j++)
      Ei[j] = zero;

    /* Accumulate A[i][k] * B[k][j] into row i of E. */
    for (k = 0; k < nk_pb; ++k)
    {
      const DATA_TYPE aik = A_[i][k];
      const DATA_TYPE *restrict Bk = B_[k]; /* row k of B */

      /* Inner loop over j is contiguous in both Ei and Bk and has
       * no loop-carried dependencies, which is ideal for vectorization.
       */
      for (j = 0; j < nj_pb; ++j)
        Ei[j] += aik * Bk[j];
    }
  }

  /* F := C*D
   *
   * Same optimization strategy as for E:
   *   C is (nj x nm), D is (nm x nl), F is (nj x nl).
   *   Access pattern: for each i (row of C/F), walk k over C,
   *   and j over row of D[k] and row of F[i].
   */
  for (i = 0; i < nj_pb; i++)
  {
    DATA_TYPE *restrict Fi = F_[i];

    /* Initialize row i of F. */
    for (j = 0; j < nl_pb; j++)
      Fi[j] = zero;

    /* Accumulate C[i][k] * D[k][j] into row i of F. */
    for (k = 0; k < nm_pb; ++k)
    {
      const DATA_TYPE cik = C_[i][k];
      const DATA_TYPE *restrict Dk = D_[k]; /* row k of D */

      for (j = 0; j < nl_pb; ++j)
        Fi[j] += cik * Dk[j];
    }
  }

  /* G := E*F
   *
   * E is (ni x nj), F is (nj x nl), G is (ni x nl).
   * We again use i, (initialize row), k, j with inner j-loop.
   *
   * For any fixed (i,j):
   *   - We write G[i][j] = 0 once.
   *   - Then we add E[i][k] * F[k][j] in order of k = 0..nj-1.
   * This matches the original per-element operation order and thus
   * preserves floating-point semantics for each output entry.
   */
  for (i = 0; i < ni_pb; i++)
  {
    DATA_TYPE *restrict Gi = G_[i];

    /* Initialize row i of G. */
    for (j = 0; j < nl_pb; j++)
      Gi[j] = zero;

    /* Accumulate E[i][k] * F[k][j] into row i of G. */
    for (k = 0; k < nj_pb; ++k)
    {
      const DATA_TYPE eik = E_[i][k];
      const DATA_TYPE *restrict Fk = F_[k]; /* row k of F */

      for (j = 0; j < nl_pb; ++j)
        Gi[j] += eik * Fk[j];
    }
  }
#pragma endscop

